# handling UE side of iperf
from ...exceptions import UeProcedureError
from . import host
from .endpoint import IperfEndpoint


class UeEndpoint(IperfEndpoint):
    """Managing UE side of iperf data transfer."""
    def __init__(self, name, dt_definition, configuration, cmd_options, logger):
        """
        Basic initialization.

        :param name: name assigned to DataTransfer object
        :param dt_definition: DataTransferDefinition object - definition of data transfer characteristics
        :param configuration: configuration
        :param cmd_options: CmdOptions instance
        :param logger: logger to use
        """
        super().__init__(name=name, dt_definition=dt_definition,
                                         configuration=configuration, cmd_options=cmd_options)
        self._validate_ue_config()
        iperf_host = self._configuration['ue_host']
        self.host_device = host.get_device(device_def=iperf_host,
                                           data_traffic_name=self._name,
                                           endpoint_name='UE', logger=logger)

    def _validate_ue_config(self):
        err_msg = ''
        if 'ue_ip' not in self._configuration:
            err_msg += "\n missing ue_ip key"
        if 'ue_host' not in self._configuration:
            err_msg += "\n missing ue_host key"
        if err_msg:
            example = {
                'ue_ip': '192.168.44.50',  # iperf target in DL, iperf binding IP in UL
                'ue_host': 'UE_1_SHELL',  # where to start iperf on
            }
            msg = f"expected cfg like: 'data_transfer': {example}; got: 'data_transfer': {self._configuration}{err_msg}"
            raise UeProcedureError(msg)

    @property
    def iperf_path(self):
        """Return path to iperf at UE side"""
        try:
            path = self._configuration['iperf']['path']
        except KeyError:
            path = None
        return path

    @property
    def iperf_port(self):
        """Return port to use by iperf at UE side"""
        protocol_details = self._dt_definition.protocol_details
        port = 5001
        if 'port' in protocol_details:
            port = protocol_details['port']
        else:
            try:
                port = self._configuration['iperf']['port']
            except KeyError:
                pass
        if port is not None:
            port = int(port)
        return port

    @property
    def endpoint_ip(self):
        """IP of UE"""
        # We shell not take IP from UE_PC host or localhost
        # This must be same IP as it is used in LTE when UE sends data, so
        # it is either:
        # 1) IP of first default bearer assigned during attach
        #    IP is in NAS Attach Accept carried by RRC Connection Reconfiguration, or
        # 2) IP of next default bearer
        #    Initiated by UE:  NAS PDN CONNECTIVITY REQUEST carried by UL Information Transfer
        #    which results in response sent to UE:
        #    IP is in NAS Activate Default EPS Bearer Context Request carried by RRC Connection Reconfiguration

        # WE SHOULD TAKE IP from UE
        # PRECISELY from default bearer since we may have multiple default bearers pointing different PDNs
        # So, we require ue_ip passed in configuration by UE that is creating given DataTransfer
        #     UE is responsible for extracting correct IP from correct default bearer
        #     based on bearer specified as parameter to start_data_transfer()
        #     (dedicated bearers have LBI attribute which indicates default bearer they are connected to)
        ip = self._configuration['ue_ip']  # existence ensured by _validate_ue_config()
        return ip

    @property
    def host_bind_interface_ip(self):
        """Return IP of UE host interface intended to bind to"""
        # as default we bind to endpoint_ip of host (which is ue_ip here)
        # but derived classes may have different ue_ip and UE-host-bindingIP
        return self.endpoint_ip

    def seen_ip_of_other_endpoint(self, other_endpoint_ip):
        """IP of AppServer as seen by UE host"""
        # default is 1:1 IP as taken from application_server.endpoint_ip
        # but derived classes may change it
        # f.ex. if they use NAT proxy
        return other_endpoint_ip

    @property
    def need_root(self):
        """Return True if iperf needs to be run inside shell of root user"""
        try:
            need_root = self._configuration['iperf']['need_root']
        except KeyError:
            need_root = False
        return need_root

    @property
    def device_target_state(self):
        """Target state of moler device required to run iperf from (UE side)"""
        start_point_and_root_to_state = {('ue_pc', False): 'UNIX_REMOTE',
                                         ('ue_pc', True): 'UNIX_REMOTE_ROOT',
                                         ('adb_shell', False): 'ADB_SHELL',
                                         ('adb_shell', True): 'ADB_SHELL_ROOT'}
        try:
            if self.host_device.__class__.__name__ == 'UnixLocal':
                return 'UNIX_LOCAL_ROOT' if self.need_root else 'UNIX_LOCAL'
            start_point = self._configuration['iperf']['start_from']
        except KeyError:
            return 'UNIX_REMOTE'
        try:
            state = start_point_and_root_to_state[(start_point, self.need_root)]
        except KeyError:
            msg = "{} - incorrect value of iperf/start_from. Allowed values {}".format(start_point,
                                                                                       'ue_pc, adb_shell')
            raise UeProcedureError(msg)
        return state

    @property
    def sudo_password(self):
        """Password required when iperf needs to start via sudo at UE side"""
        password = ''
        iperf_host = self._configuration['ue_host']
        if isinstance(iperf_host, dict):
            password = iperf_host.get('password', '')
        elif hasattr(self, 'host_device'):
            # take it from ssh command or ssh io
            password = host.find_ssh_passwd(host_device=self.host_device)
        return password

    @property
    def need_sudo(self):
        """Return True if running iperf requires sudo"""
        sudo_port = 1024  # default, accessing ports below 1024 requires sudo
        try:
            if 'need_sudo' in self._configuration['iperf']:
                unconditional_sudo = self._configuration['iperf']['need_sudo']
                if unconditional_sudo:
                    return True
            sudo_rule = self._configuration['iperf']['use_sudo_when']
            if sudo_rule.startswith('port<'):
                _, _, sudo_port = sudo_rule.partition("<")
                sudo_port = int(sudo_port)
        except KeyError:
            pass

        return self.iperf_port < sudo_port

    def client_options(self, app_server_ip, app_server_iperf_port=None):
        """
        Generate options for iperf client command

        :param app_server_ip: UeEndpoint has no knowledge about IP of other end (AppSvr), it must be provided.
        :param app_server_iperf_port: same as above
        :return: iperf options string
        """
        server_ip = self.seen_ip_of_other_endpoint(app_server_ip)
        client_ip = self.host_bind_interface_ip
        # inside iperf client options:
        # - client_ip is used for binding to IP at client side
        # - server_ip is used for:
        #   - defining where iperf client should connect to
        #   - detecting if IPv6 should be used at server side
        return self._cmd_options.client_options(client_ip, server_ip, port=app_server_iperf_port)

    def server_options(self, app_server_ip):
        """
        Generate options for iperf server command

        :param app_server_ip: UeEndpoint has no knowledge about IP of other end (AppSvr), it must be provided.
        :return: iperf options string
        """
        server_ip = self.host_bind_interface_ip
        client_ip = self.seen_ip_of_other_endpoint(app_server_ip)
        # inside iperf server options:
        # - server_ip is used for binding to IP at server side
        # - client_ip is used for detecting if IPv6 should be used at server side
        return self._cmd_options.server_options(client_ip, server_ip, port=self.iperf_port)

    def get_client_command_object(self, app_server_ip, app_server_iperf_port=None):
        """Return moler Command object for iperf client"""
        iperf_client_options = self.client_options(app_server_ip, app_server_iperf_port)
        iperf_client_cmd = self._get_iperf_command_object(iperf_options=iperf_client_options)
        return iperf_client_cmd

    def get_server_command_object(self, app_server_ip):
        """Return moler Command object for iperf server"""
        iperf_server_options = self.server_options(app_server_ip)
        iperf_server_cmd = self._get_iperf_command_object(iperf_options=iperf_server_options)
        return iperf_server_cmd

    def _get_iperf_command_object(self, iperf_options):
        iperf_cmd = host.get_iperf_command_object(host_device=self.host_device,
                                                  iperf_options=iperf_options,
                                                  iperf_path=self.iperf_path,
                                                  need_sudo=self.need_sudo,
                                                  sudo_password=self.sudo_password)
        return iperf_cmd

    def prepare_host_device(self):
        """Change host device state to expected target state"""
        self.host_device.goto_state(state=self.device_target_state)
